void app_main( void )
{
    /* Start the MPU demo. */
    vStartMPUDemo();

    /* Start the scheduler. */
    vTaskStartScheduler();

    printf( "Returned from vTaskStartScheduler something bad had happened\n" );

    /* Should not get here. */
    for( ; ; )
    {
    }
