        KEEP (*(.fini))
        KEEP(*(.eh_frame))
        . = ALIGN(4);
        _etext = .;
    } > FLASH


    .rodata :
    {
        . = ALIGN(4);
        *(.rodata)         /* .rodata sections  (constants, strings, etc.). */
        *(.rodata*)        /* .rodata* sections (constants, strings, etc.). */
        . = ALIGN(4);

