        prvReportPropertyCheck( xWriteStillRejected, SP2_PASS_MESSAGE, SP2_FAIL_MESSAGE );
    }
    #else /* if ( configENFORCE_SYSTEM_CALLS_FROM_KERNEL_ONLY == 1 ) */
